import re
import time
import logging
import six
from abc import ABCMeta, abstractmethod
from taf.ue.plugin.mtk.exceptions import DeleteRoutineTimeout, RndisStartupFailure, GetRndisFailure


@six.add_metaclass(ABCMeta)
class SystemCommand(object):

    @abstractmethod
    def create_routine(self, core_appserver_ip=None, ue_ip=None):
        raise NotImplementedError


class WindowsSystemCmd(SystemCommand):
    def __init__(self, executor=None):
        self._executor = executor

    def _get_routine(self, dest):
        cmd = 'cmd /C "route print {}"'.format(dest)
        return self._executor.execute(cmd)

    def _delete_routine(self, dest):
        cmd = 'cmd /C "route delete {}"'.format(dest)
        self._executor.execute(cmd)

    def _delete_routine_if_exist(self, dest, timeout=60):
        time_interval = 1
        start_time = time.time()
        while True:
            if dest not in self._get_routine(dest):
                break
            else:
                self._delete_routine(dest)
            time.sleep(time_interval)
            if time.time() - start_time > timeout:
                raise DeleteRoutineTimeout("delete routine failed.")
        logging.info("delete exist routine successfully.")

    def create_routine(self, dest=None, gateway=None):
        self._delete_routine_if_exist(dest)

        if_index = self.get_interface_index()
        mask = '255.255.255.255'
        metric = 5
        cmd = 'cmd /C "route add {dest} MASK {mask} {gateway} metric {metric} IF {if_index}"'.\
            format(dest=dest, mask=mask, gateway=gateway, metric=metric, if_index=if_index)
        self._executor.execute(cmd)
        self._get_routine(dest)

    def _get_rndis_address(self):
        cmd = 'netsh interface ip show address "{interface_name}"'.format(interface_name=self.get_interface_name())
        return self._executor.execute(cmd)

    def _check_rndis_if_available(self, timeout=60):
        time_interval = 2
        ip_available = 'IP Address'
        start_time = time.time()
        while True:
            if ip_available in self._get_rndis_address():
                break
            time.sleep(time_interval)
            if time.time() - start_time > timeout:
                raise RndisStartupFailure("rndis interface start up failed.")
        logging.info("rndis interface start up successfully.")

    def check_ip_bind(self, ip):
        self._check_rndis_if_available()

        cmd = 'cmd /C ipconfig'
        out = self._executor.execute(cmd)
        regex_result = re.search(r'IPv4 Address.*\s{}'.format(ip), out)
        return True if regex_result else False

    def _get_rndis_param(self, param):
        cmd = 'wmic nic where "NetEnabled=True and ProductName=\'Remote NDIS based Internet Sharing Device\'" get {}'.format(param)
        out = self._executor.execute(cmd)

        param_result = None
        for line in out.split('\n'):
            line = line.strip()
            if line not in ['', param]:
                param_result = line

        if not param_result:
            raise GetRndisFailure("failed to get rndis {}".format(param))
        return param_result

    def get_interface_name(self):
        return self._get_rndis_param(param='NetConnectionID')

    def get_interface_index(self):
        return self._get_rndis_param(param='InterfaceIndex')

    def config_rndis(self, ue_ip):
        interface_name = self.get_interface_name()
        mask = '255.255.255.0'
        metric = 265
        gateway = self.get_gateway(ue_ip)
        cmd = 'netsh interface ipv4 set address name="{name}" static {ip_address} {mask} {gateway} {metric}'.\
            format(name=interface_name, ip_address=ue_ip, mask=mask, gateway=gateway, metric=metric)
        self._executor.execute(cmd)
        logging.info("set rndis interface address command executed finished.")

    @staticmethod
    def get_gateway(ip):
        gateway = ip.split('.')
        gateway[-1] = str(int(gateway[-1]) + 1)
        return '.'.join(gateway)
